/**
 * Filters all status notification entries loaded from Firebase
 * and returns only unprocessed notifications.
 *
 * Purpose:
 * - Extracts pending notification items from the Firebase object map
 * - Preserves the original notification id for later update requests
 * - Prevents already processed notifications from being mailed twice
 *
 * Output:
 * - notificationId: Firebase key of the notification entry
 * - remaining notification fields from the original object
 */

const notifications = $json || {};

return Object.entries(notifications)
  .filter(([id, item]) => item && item.processed === false)
  .map(([id, item]) => ({
    json: {
      notificationId: id,
      ...item
    }
  }));

/**
 * Builds the outgoing status update email for a ticket creator.
 *
 * Purpose:
 * - Translates internal Join column ids into readable status labels
 * - Uses the stored creator email as recipient
 * - Generates a user-friendly plain text update about the column change
 *
 * Output:
 * - notificationId: Firebase key used for post-send processing
 * - toEmail: creator email address
 * - subject: status update subject line
 * - text: plain text status update message
 */

const columnLabels = {
  triage: "Triage",
  toDo: "To Do",
  inProgress: "In Progress",
  review: "Review",
  done: "Done",
};
const previousLabel =
  columnLabels[$json.previousColumnId] || $json.previousColumnId;
const newLabel = columnLabels[$json.newColumnId] || $json.newColumnId;
const creatorName = $json.creatorName || "there";

return [
  {
    json: {
      notificationId: $json.notificationId,
      toEmail: $json.creatorEmail,
      subject: `Status update for your ticket: ${$json.taskTitle}`,
      text: `Hello ${creatorName},

your ticket in the Join board has been updated.

Ticket title: ${$json.taskTitle}
Previous status: ${previousLabel}
New status: ${newLabel}

Best regards
Join Team`,
    },
  },
];
